local quests = WordHunterWoW_QuestDataByFlavor.classic.deDE
quests[3982] = { title = "Was ist los?", description = "Ich wurde unter der Schirmherrschaft von Thrall hierher geschickt. Glaubt Ihr wirklich, diese Clowns könnten mich fangen? Ich habe mich fangen lassen, um so Informationen sammeln zu können.\n\n<Gor'shak flüstert.>\n\nDie Prinzessin von Ironforge wurde von Imperator Thaurissan entführt. Prinzessin Bronzebeard befindet sich in dieser Stadt! Ich wette, dem alten Magni ist fast das Herz stehen geblieben, als er diese Neuigkeiten gehört hat.\n\n<Gor'shak lacht.>\n\nPssst! Hört Ihr das? Es kommen Wachen! VERTEIDIGT EUCH!", objectives = "Verteidigt Gor'shak.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[4001] = { title = "Was ist los?", description = "Bisher war meine Kommunikation mit dem Zwerg Kharan in der Zelle auf der anderen Seite der Halle nur sehr eingeschränkt möglich. Doch ich konnte ihn immerhin davon überzeugen, dass ich - oder besser - dass wir ihm nichts Böses wollen.\n\nGeht und redet mit ihm und erfahrt so viel über die Prinzessin und ihre Entführer wie nur möglich. Bringt diese Informationen dann dem Kriegshäuptling.\n\nThrall will nicht, dass der Prinzessin ein Leid geschieht. Er hat irgendeinen großen Plan, und der umfasst auch, dass sie wieder sicher nach Ironforge zurückgebracht wird. Kharan weiß das alles schon ... Geht!", objectives = "Sprecht mit Kharan Mighthammer und sammelt Informationen über die Entführung von Prinzessin Moira Bronzebeard. Bringt diese Informationen dann zu Thrall nach Orgrimmar.\n\nIhr erinnert Euch, dass Gor'shak gesagt hat, Kharan werde in einer Zelle in seiner Nähe festgehalten.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[4002] = { title = "Das östliche Königreich", description = "Ihr bringt ganz ausgezeichnete Nachrichten, $N.\n\nAls Kriegshäuptling ist es meine Aufgabe, das zu tun, was das Beste für die Horde ist. Zu garantieren, dass die nachfolgenden Generationen nicht in einer hoffnungslosen Existenz gefangen sein werden.\n\nJetzt ist uns die einzigartige Chance, die Allianzen der Zukunft zu formen, in den Schoß gefallen. Wenn wir jetzt den Zwergen helfen, könnte dies unsere Beziehungen zum östlichen Königreich enorm verbessern. Und aus genau diesem Grund dürft Ihr nicht versagen!\n\nSeid Ihr bereit?", objectives = "Sprecht mit Thrall, wenn Ihr bereit seid, die von ihm geplante Mission zu übernehmen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[4003] = { title = "Die königliche Rettung", description = "Der Schlag gegen die Dunkeleisenzwerge wird, wenn er denn erfolgreich verläuft, eine Schockwelle durch ihr ganzes Königreich jagen.\n\nPrinzessin Bronzebeard ist unter der Kontrolle von Imperator Thaurissan. Um sie zu befreien, müsst Ihr den Imperator töten. Doch seid gewarnt, denn Eure Aufgabe ist doppelt gefährlich. Zweifellos wird Euch Prinzessin Bronzebeard angreifen, solange sie noch der Kontrolle des Imperators unterliegt.\n\nIHR DÜRFT IHR KEIN LEID ZUFÜGEN!", objectives = "Tötet Imperator Dagran Thaurissan und befreit Prinzessin Moira Bronzebeard von seinem bösen Zauber.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[4004] = { title = "Ist die Prinzessin gerettet?", description = "Ihr habt meinen Ehemann erschlagen, $R! Mein Kind wird ohne Vater in diese Welt geboren werden.\n\n<Prinzessin Moira zeigt direkt auf Euch.>\n\nIch versichere Euch, dieses Kind wird der nächste Herrscher des Königreichs von Ironforge sein. Ihr und Eure Art solltet für diese ungerechte Tat bis ans Ende aller Tage gejagt werden.\n\n<Ihr denkt, dass Prinzessin Moira vielleicht unter den Nachwirkungen von Thaurissans Zauber leidet.>\n\nLasst mich in Ruhe, $R. Ich bin sicher, Euer Kriegshäuptling ist erpicht darauf, vom Ergebnis seiner Einmischung zu erfahren.", objectives = "Kehrt zu Thrall zurück!", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[4005] = { title = "Aquementas", description = "Nehmt diese Tasche mit Vorräten mit Euch nach Tanaris. Begebt Euch zur Lost Rigger-Bucht und sucht dort einen Kreis aus Steinen.\n\nIn der östlichsten Halbinsel liegt das Geheimnis...\n\nLest aus dem Buch von Aquor vor - aber nur innerhalb dieses Kreises - und beschwört das einzige Wesen, das die Gegenstände, die Ihr gesammelt habt, in ein Totem verwandeln kann, mit dem Ihr Sturmflamme bekämpfen könnt.\n\nEs wird Aquementas nicht gefallen, dass Ihr ihn aufweckt, doch vergesst nicht: Ihr müsst unbedingt in dem Kreis bleiben, damit er die Gegenstände transformieren kann.", objectives = "Bringt das Buch von Aquor, die silbrigen Klauen und das Eisenstammherz nach Tanaris.\n\nBenutzt das Buch von Aquor, um Aquementas zu beschwören.\n\nWenn Ihr das vollständige Totem habt, bringt es zu J.D. Collie in Marshals Zuflucht zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[4021] = { title = "Gegenangriff!", description = "Die Horde lobt Euch für Eure Erfolge gegen die Kolkar, doch die Kolkar kochen vor Wut. Ich habe Berichte erhalten, denen zufolge ein Kontingent Kolkar ihr Zuhause in Desolace verlassen hat und ins Brachland gezogen ist, um dort Rache zu üben. Den letzten Berichten nach, rücken Sie in diesem Moment von Westen her gegen diese Bunker vor!\n\nStellt Euch den Eindringlingen der Kolkar und bereitet der Bedrohung, die sie für das Brachland darstellen, ein Ende. Tötet sie, bis ihr Anführer, Kriegsherr Krom'zar, erscheint. Besiegt ihn und bringt mir ein Teil seiner Flagge als Beweis.\n\nWir zählen auf Euch, $n.", objectives = "Bringt ein Teil von Krom'zars Flagge zu Regthar Deathgate, westlich von Crossroads.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[4022] = { title = "Eine Kostprobe der Flamme", description = "Der Klan ist sich Eurer Arbeit in der sengenden Schlucht bewusst.\n\nZeigt sie mir, $R. Die abgestreifte Drachenhaut, Schwachkopf!", objectives = "Zeigt Cyrus Therepentous die abgestreifte Haut des schwarzen Drachenschwarms, die Ihr von Kalaran Windblade erhalten habt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[4023] = { title = "Eine Kostprobe der Flamme", description = "Ihr sucht nach dem Klan? Zeigt mir einen Beweis für Eure Nützlichkeit, sterbliches Wesen.", objectives = "Zeigt Cyrus Therepentous einen Beweis für Eure Nützlichkeit.\n\nIhr habt so ein Gefühl, dass Cyrus bereits weiß, dass Ihr unwürdig seid.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[4024] = { title = "Eine Kostprobe der Flamme", description = "Ich möchte die sengenden Flammen des Feuerberges schmecken. Die flüssigen Feuer des Blackrock über mich strömen lassen. Diese Essenz, diese sengende Hitze ist es, nach der ich mich sehne.\n\nIn den Tiefen des Blackrock haust Bael'Gar: ein Wesen aus reinstem Feuer, geboren aus den Flammen des Ragnaros. Tötet Bael'Gar und bringt mir aus seinen glimmenden Überresten einen Teil seines inneren Feuers.\n\nVerwendet die Drachenhaut für seine Überreste, um die innere Flamme sicher entnehmen zu können.\n\nSeid erfolgreich und Ihr werdet belohnt.", objectives = "Begebt Euch in die Blackrocktiefen und tötet Bael'Gar.\n\nIhr wisst lediglich, dass der Riese irgendwo in den Blackrocktiefen haust. Vergesst nicht, die veränderte Haut des schwarzen Drachenschwarms mit Bael'Gars Überresten zu benutzen und damit die feurige Essenz einzufangen.\n\nBringt die eingeschlossene feurige Essenz zu Cyrus Therepentous zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[4041] = { title = "Das Videre-Elixier", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[4061] = { title = "Aufstieg der Maschinen", description = "Wir stießen bereits bei unseren ersten Streifzügen in der sengenden Schlucht auf die Maschinen. Weitere Nachforschungen ergaben, dass sie aus der brennenden Steppe, eventuell auch aus den Blackrocktiefen, stammen. Und dafür brauchen wir Euch, $N.\n\nEure erste Aufgabe besteht darin, Euch in die brennende Steppe zu begeben und dort einige Elementarsplitter von den Felsautomatons und den geringen Felsgeschöpfen der Gegend zu beschaffen. Sobald Ihr eine ausreichende Menge gesammelt habt, kehrt zu mir zurück, dann werde ich herausfinden, woher sie wirklich stammen.", objectives = "Begebt Euch in die Brennende Steppe und beschafft für Theodora Mulvadania 10 gerissene Elementarsplitter.\n\nEuch fällt ein, dass Theodora gesagt hat, die Golems und Elementare in der Gegend seien eine gute Quelle für solche Splitter.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[4062] = { title = "Aufstieg der Maschinen", description = "G.L.A.\n\nDas sind die Buchstaben, die in die Elementarsplitter eingeprägt sind. Unter den Initialen findet sich eine Markierung für einen Rang oder etwas in der Art. Die Maschinen, die Ihr in der Brennenden Steppe zerstört habt, hatten den 'Rang IV'. Ich nehme an, das ist ein eher niedriger Rang.\n\nBringt diese Splitterprobe in das Lager im Osten zu Lotwil Veriatus. Er ist ein Gelehrter und vor allem für seine Arbeit auf dem Gebiet der Elementarforschung bekannt. Vielleicht kann er uns bei unserer Suche helfen.", objectives = "Bringt die Elementarsplitterprobe zu Lotwil Veriatus.\n\nIhr erinnert Euch, dass Theodora sagte, Lotwil sei in einem Lager im Osten stationiert.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[4063] = { title = "Aufstieg der Maschinen", description = "Das kann doch nicht Argelmach sein... Argelmach wurde vor zehn Jahren getötet. Warum ich das so genau weiß? Weil ich derjenige war, der ihn getötet hat.\n\nEr war ein abscheulicher Zwerg und wild entschlossen, mein Lebenswerk zu verderben und es für seine teuflischen Zwecke zu benutzen. Wie es scheint, finden die Tückischen immer einen Weg, ihrer gerechten Strafe zu entgehen.\n\nWenn dies Argelmachs Werk ist, dann muss er zerstört werden. Ich brauche Proben seiner jüngsten Schöpfungen. Mit den richtigen Proben kann ich vielleicht diesem Aufstand ein Ende machen. Die Schöpfungen bewachen Argelmach in den Blackrocktiefen.", objectives = "Sucht und tötet Golemlord Argelmach. Bringt Lotwil seinen Kopf. Außerdem müsst Ihr 10 intakte Elementarkerne von den Wuthäschergolems und Kriegshetzerkonstrukten, die Argelmach beschützen, beschaffen. Das wisst Ihr, weil Ihr übernatürliche Fähigkeiten habt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[4081] = { title = "SOFORT TÖTEN: Dunkeleisenzwerge", description = "Auf Befehl von Kriegsherr Goretooth, Kommandant des Expeditionskorps von Kargath:\n\nAlle Streitkräfte, über die General Zornesschmied in den Blackrocktiefen verfügt, müssen ausgelöscht werden.\n\nZornesschmieds Männer sind rücksichtslose Killer und verantwortlich für den Massenmord an der 109. Division des Expeditionskorps von Kargath. Alle Helden, die diesen gefühllosen Bestien gegenübertreten wollen, werden aufgefordert, extreme Vorsicht walten zu lassen.\n\nJede Person, die die erste Kampfreihe von General Zornesschmieds Streitkräften in den Blackrocktiefen vernichtet, wird einen Tribut erhalten.", objectives = "Begebt Euch in die Blackrocktiefen und vernichtet die üblen Aggressoren!\n\nKriegsherr Goretooth möchte, dass Ihr 15 Gardisten der Zorneshämmer, 10 Aufseher der Zorneshämmer und 5 Fußsoldaten der Zorneshämmer tötet. Kehrt zu ihm zurück, sobald Ihr die Aufgabe erfüllt habt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[4082] = { title = "SOFORT TÖTEN: Hochrangige Führungskräfte der Dunkeleisenzwerge", description = "Auf Befehl von Kriegsherr Goretooth, Kommandant des Expeditionskorps von Kargath:\n\nDer Leiter der Aufklärungseinheit des KEK, Großmeister Lexlort, kam mit Neuigkeiten über den Verbleib einiger hochrangiger Führungskräfte der Dunkeleisenzwerge zurück. Hinter dem verschlossenen Tor, nahe dem Herzen der Stadt, bilden sie ihre Streitkräfte darin aus, unsere Männer auszulöschen. Geht in die Blackrocktiefen und vernichtet sie!\n\nWer diese Mission erfüllt, erhält einen Tribut.", objectives = "Begebt Euch in die Blackrocktiefen und vernichtet die üblen Aggressoren!\n\nKriegsherr Goretooth möchte, dass Ihr 10 Sanitäter der Zorneshämmer, 10 Soldaten der Zorneshämmer und 10 Offiziere der Zorneshämmer tötet. Kehrt zu ihm zurück, sobald Ihr die Aufgabe erfüllt habt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[4083] = { title = "Der spektrale Kelch", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[4084] = { title = "Silberherz", description = "Ich kenne denjenigen nicht, von dem Ihr sprecht, $N.\n\nDoch keine Sorge, wenn Euer Freund auf der Suche nach mir war, dann weiß ich, was er von mir wollte.\n\nIm Herzen des Un'Goro Kraters lebt das Böse in seiner reinsten Form. Dort manifestiert es sich in der Gestalt eines Elementars namens Sturmflamme. Er wird wird von einer Aura beschützt, die niemand durchdringen kann.\n\nNiemand... außer denen, die über genügend Macht verfügen. Diese Macht kann ich Euch lehren, $N.\n\nDoch zunächst müsst Ihr mir eine Bitte erfüllen. Beschafft 11 silbrige Klauen und 1 Eisenstammherz von den Kreaturen im Teufelswald und kommt dann zu mir zurück.", objectives = "Beschafft 11 silbrige Klauen und 1 Eisenstammherz für Eridan Bluewind im Teufelswald.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[4101] = { title = "Den Teufelswald säubern", description = "Die Pflanzen schenken dem Teufelswald Leben, doch sogar sie leiden unter der Besudelung der Verderbnis. Ich kenne Wege, um sie zu säubern, doch dieses Wissen kann ich an niemanden weitergeben, den ich nicht kenne oder dem ich nicht vertraue. Beweist mir, dass Ihr der Sache des Zirkels des Cenarius wirklich helfen wollt!\n\nNördlich von hier liegen die Eisenstammhöhlen. Für die Wucherborkenelementare, die sich dort aufhalten, gibt es keine Hoffnung mehr auf Säuberung. Ich bitte Euch, bringt mir ihren Saft, er wird Blutharz genannt, damit ich ihn studieren kann. Vielleicht gelingt es mir so, die anderen Lebensformen hier zu retten.", objectives = "Bringt 15 Einheiten Blutharz zu Arathandris Silversky im Teufelswald.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[4102] = { title = "Den Teufelswald säubern", description = "Die Pflanzen schenken dem Teufelswald Leben, doch sogar sie leiden unter der Besudelung der Verderbnis. Ich kenne Wege, um sie zu säubern, doch dieses Wissen kann ich an niemanden weitergeben, den ich nicht kenne oder dem ich nicht vertraue. Beweist mir, dass Ihr der Sache des Zirkels des Cenarius wirklich helfen wollt!\n\nNördlich von hier liegen die Eisenstammhöhlen. Für die Wucherborkenelementare, die sich dort aufhalten, gibt es keine Hoffnung mehr auf Säuberung. Ich bitte Euch, bringt mir ihren Saft, er wird Blutharz genannt, damit ich ihn studieren kann. Vielleicht gelingt es mir so, die anderen Lebensformen hier zu retten.", objectives = "Bringt 15 Einheiten Blutharz zu Maybess Riverbreeze im Teufelswald.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
