quests[4401] = { title = "Verderbte Liedblume", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[4402] = { title = "Galgars Kaktusapfel Surprise", description = "Hier im Tal der Prüfungen wird es ganz schön heiß.\n\n<Galgar wischt sich den Schweíß von der Stirn.>\n\nWenn ich doch nur ein paar Kaktusäpfel hätte, dann könnte ich meinen berühmten Kaktusapfel Surprise machen! Nichts kühlt einen schneller ab als ein Stück dieser leckeren Spezialität.\n\nIch sag Euch was, $N. Wenn Ihr mir 10 Kaktusäpfel bringt, dann mache ich Euch ein paar Portionen Kaktusapfel Surprise, die Ihr mit auf Eure Abenteuer nehmen könnt. Falls Ihr daran interessiert seid, findet Ihr Kaktusäpfel bei den Kaktuspflanzen, die hier in der Gegend wachsen.", objectives = "Bringt Galgar 10 Kaktusäpfel. Ihr erinnert Euch, dass er gesagt hat, man fände sie in der Nähe von Kakteen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[4403] = { title = "Verderbte Windblüte", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[4421] = { title = "Die Verderbnis der Jadefeuer", description = "Nicht viele kommen hierher und suchen das Abenteuer... Die Verderbnis hat sich im Teufelswald überall ausgebreitet und macht vor nichts Halt.\n\nAls Mitglied des Smaragdkreises trachte ich danach, dieses Land zu heilen. Doch es gibt andere, die wünschen, dass es weiter schwärt.\n\nIch spreche von den Jadefeuersatyrn, die sich südwestlich von hier aufhalten, bei den Ruinen von Constellas. Ihr Anführer ist ein besonders grausamer Satyr namens Xavathras und unter seiner Führung übertragen sie die Krankheit auf alle Wesen, denen sie begegnen.\n\nWir müssen dieses Land, das einst das unsrige war, verteidigen. Besiegt Xavathras und vernichtet seine Diener.", objectives = "Tötet Xavathras sowie 11 Jadefeuerteufelsanbeter, 9 Jadefeuerschattenpirscher und 9 Jadefeuerschurken. Kehrt zu Eridan Bluewind im Teufelswald zurück, sobald die Aufgabe erledigt ist.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[4441] = { title = "Gebundene Urtume", description = "Die Flöte, die Ihr gefunden habt, wurde aus einem Urtumbeschützer geschnitzt, den Treantverbündeten, die schon immer treu über die Nachtelfen gewacht haben.\n\nEs ist den Satyrn gelungen, alles zu verderben, mit dem sie in Kontakt kommen, einschließlich der Urtume, die im Teufelswald lebten. Mit Hilfe der teuflischen Verderbnis wurde der Geist des Urtums gefangen und gefoltert und nie wieder völlig freigegeben. Der Teufelsbinder, den Ihr gefunden habt, hängt ganz ohne Zweifel damit zusammen.\n\nWir müssen versuchen, die Flöte zu läutern, $N. Bringt mir gesegnetes Wasser vom Tempel des Mondes in Darnassus.", objectives = "Begebt Euch nach Darnassus und verwendet Eridans Phiole, um Euch im Tempel des Mondes eine Phiole mit gesegnetem Wasser zu holen. Kehrt mit der gefüllten Phiole zu Eridan zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[4442] = { title = "Geläutert!", description = "Ich werde jetzt versuchen, die Flöte mit dem Wasser von Elune zu läutern. Wir müssen diesem Leiden ein Ende machen...\n\nMöge Elune meine Hände und mein Herz leiten.\n\nSprecht mich gleich noch einmal an.", objectives = "Sprecht Eridan gleich noch einmal an.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
