quests[4449] = { title = "Eingesperrt!", description = "He! He, Ihr da! Kommt her!\n\nIhr müsst mir dringend helfen. Ich bin vor den Dunkeleisenzwergen abgehauen und hab mich hier drin versteckt, damit se mich nich' sehen. Verdammte Drecksgeologen und ihre Magie! Die müss'n geseh'n haben, wie ich mich versteckt hab, weil als Allernächstes ham se die Tür versperrt. Ham was gesagt von wegen, dass sie zurückkommen und mich holen würden, und dann sind sie verschwunden.\n\nIhr müsst denen zeigen, wer hier der Boss ist! Könnt Ihr das für mich tun? Verpasst den Geologen 'ne Lektion! Ach, und könnt Ihr mir 'n paar Stücke Seidenstoff beschaffen für ... für ... ach, für nix.", objectives = "Tötet 8 Geologen der Dunkeleisenzwerge und bringt der Person, die im Plumpsklo in der Sengenden Schlucht eingesperrt ist, 15 Stücke Seidenstoff.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[4450] = { title = "Geschäftsbuch aus Tanaris", description = "Ach, wisst Ihr was? Da fällt mir grade was ein.\n\nWo ich doch immer noch hier drin festsitz: Wollt Ihr nich' vielleicht 'n kleinen Job für mich fertig machen, den ich angenommen hab, als ich in Tanaris war? Is' auch ganz einfach... na ja, wenn man nich' grade hier drin sitzt, jedenfalls.\n\nKrinkle Goodsteel in Gadgetzan war scharf auf so'n paar Sachen, die hier in der sengenden Schlucht und an 'n paar anderen Orten gefunden wurden. Vielleicht könnt Ihr Euch ja die Liste einmal ansehen und ihm den Kram dann bringen?\n\nIch schieb Euch sein Geschäftsbuch unter der Tür durch, wenn Ihr interessiert seid. Bringt es ihm zusammen mit dem Zeug, das er will, nachdem Ihr den ganzen Kram eingesammelt habt.", objectives = "Nehmt die Abschrift von Goodsteels Geschäftsbuch und beschafft Euch dann die darin aufgeführten Gegenstände, ehe Ihr Krinkle Goodsteel in Tanaris aufsucht.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[4451] = { title = "Der Schlüssel zur Freiheit", description = "Der kleine Messingschlüssel sieht recht einfach aus. Das Einzige, was ihn von anderen seiner Art unterscheidet, sind einige Worte, die darauf eingeritzt sind:\n\n\"Dunkeleisenplumpsklo - Nicht duplizieren\".\n\nIhr habt absolut keine Ahnung, was das heißen soll oder wofür der Schlüssel gut ist.", objectives = "Sucht in der sengenden Schlucht, bis Ihr etwas findet, wofür man den Schlüssel des Grimsilt-Nebengebäudes verwenden kann, den Ihr gefunden habt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
